:root {
  --primary: #7f9cf5;
  --primary-dark: #5a67d8;
  --accent: #f6ad55;
  --bg: #f8fafc;
  --card-bg: #ffffff;
  --text: #2d3748;
  --border: #e2e8f0;
  --radius: 16px;
  --shadow: 0 4px 24px rgba(100, 116, 139, 0.08);
  --shadow-hover: 0 8px 32px rgba(100, 116, 139, 0.13);
  --badge-active: #c6f6d5;
  --badge-completed: #fed7e2;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Segoe UI', 'Roboto', Arial, sans-serif;
  background: linear-gradient(135deg, #f8fafc 0%, #e9d8fd 100%);
  color: var(--text);
  min-height: 100vh;
  transition: background 0.3s;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: transparent;
}

.container {
  max-width: 900px;
  margin: 0 auto;
  padding: 32px 12px 24px 12px;
  width: 100%;
}

.card, .voting-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px 18px;
  margin-bottom: 24px;
  border: 1px solid var(--border);
  transition: box-shadow 0.2s, border 0.2s;
  position: relative;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}
.card:hover, .voting-card:hover {
  box-shadow: var(--shadow-hover);
  border-color: var(--primary);
}

.voting-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.voting-content {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.voting-image {
  width: 100%;
  max-width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: var(--radius) var(--radius) 0 0;
  margin-bottom: 14px;
  display: block;
}

.voting-title {
  font-size: 1.4rem;
  color: var(--primary-dark);
  margin-bottom: 8px;
}

.voting-meta {
  display: flex;
  gap: 18px;
  font-size: 0.98rem;
  color: #64748b;
  margin-bottom: 10px;
}

.badge {
  display: inline-block;
  padding: 4px 14px;
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 600;
  margin-right: 8px;
}
.badge-custom {
  background: var(--badge-active);
  color: #276749;
}
.bg-secondary, .badge.bg-secondary {
  background: var(--badge-completed);
  color: #97266d;
}

/* Исправления для выравнивания и современного вида */
.d-flex {
  display: flex !important;
}
.justify-content-between {
  justify-content: space-between !important;
}
.align-items-center {
  align-items: center !important;
}
.mb-4 {
  margin-bottom: 1.5rem !important;
}
.mb-3 {
  margin-bottom: 1rem !important;
}
.mb-2 {
  margin-bottom: 0.5rem !important;
}
.py-4 {
  padding-top: 1.5rem !important;
  padding-bottom: 1.5rem !important;
}
.py-5 {
  padding-top: 2.5rem !important;
  padding-bottom: 2.5rem !important;
}
.text-center {
  text-align: center !important;
}

/* Кнопки */
.btn, .button {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 10px 24px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s;
  margin: 8px 0;
  box-shadow: 0 2px 8px rgba(127, 156, 245, 0.08);
  display: inline-block;
  text-align: center;
  text-decoration: none;
}
.btn-primary, .btn-primary-custom {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover, .btn-primary-custom:hover {
  background: #dd6b20;
}
.btn-outline-custom {
  background: transparent;
  color: var(--primary-dark);
  border: 1.5px solid var(--primary-dark);
}
.btn-outline-custom:hover {
  background: var(--primary-dark);
  color: #fff;
}

/* Grid для карточек */
.row {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 24px;
  margin-left: 0;
  margin-right: 0;
  width: 100%;
}
.col-md-6 {
  width: auto;
  padding: 0;
}

.voting-card-square {
  aspect-ratio: 1 / 1;
  width: 180px;
  height: 180px;
  min-width: 120px;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  margin-bottom: 0;
  transition: box-shadow 0.2s, border 0.2s;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  cursor: pointer;
  overflow: hidden;
  position: relative;
  margin-left: 0;
  margin-right: 0;
}

@media (max-width: 900px) {
  .voting-card-square {
    width: 120px;
    height: 120px;
    font-size: 1.1rem;
    min-width: 80px;
    min-height: 80px;
  }
}
@media (max-width: 600px) {
  .row {
    gap: 8px;
  }
  .voting-card-square {
    width: 90px;
    height: 90px;
    font-size: 0.95rem;
    min-width: 60px;
    min-height: 60px;
  }
}

/* Адаптивность */
@media (max-width: 600px) {
  .container {
    padding: 12px 2px;
  }
  .card, .voting-card {
    padding: 14px 8px;
  }
  .fab-create {
    right: 16px;
    bottom: 16px;
    width: 52px;
    height: 52px;
    font-size: 1.5rem;
  }
  button, .button {
    width: 100%;
  }
}

/* Мягкая анимация появления */
.fade-in {
  animation: fadeIn 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

::-webkit-scrollbar {
  width: 8px;
  background: #e2e8f0;
  border-radius: 8px;
}
::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 8px;
}

/* Плавающая кнопка создания голосования */
.fab-create {
  position: fixed;
  right: 32px;
  bottom: 32px;
  background: var(--accent);
  color: #fff;
  border-radius: 50%;
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.2rem;
  box-shadow: 0 4px 24px rgba(246, 173, 85, 0.18);
  z-index: 100;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s;
}
.fab-create:hover {
  background: #fbd38d;
  color: var(--accent);
  box-shadow: 0 8px 32px rgba(246, 173, 85, 0.28);
}

/* Стили для квадратных карточек */
.voting-card-square {
  aspect-ratio: 1 / 1;
  width: 180px;
  height: 180px;
  min-width: 120px;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  margin-bottom: 12px;
  transition: box-shadow 0.2s, border 0.2s;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  cursor: pointer;
  overflow: hidden;
  position: relative;
}
.voting-card-title {
  text-align: center;
  width: 100%;
  padding: 0 2px;
  word-break: break-word;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
}

.voting-modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(30, 41, 59, 0.32);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.2s;
}
.voting-modal {
  background: #fff;
  border-radius: 18px;
  box-shadow: 0 8px 40px rgba(30,41,59,0.18);
  max-width: 520px;
  width: 90vw;
  min-width: 260px;
  min-height: 220px;
  max-height: 60vh;
  padding: 32px 28px 24px 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  animation: fadeIn 0.2s;
}
.voting-modal-title {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--primary-dark);
  margin-bottom: 12px;
  text-align: center;
}
.voting-modal-desc {
  font-size: 1.08rem;
  color: #475569;
  text-align: center;
  margin-bottom: 18px;
  word-break: break-word;
}
.voting-modal-close {
  position: absolute;
  top: 12px;
  right: 18px;
  background: none;
  border: none;
  font-size: 1.5rem;
  color: #64748b;
  cursor: pointer;
  transition: color 0.2s;
}
.voting-modal-close:hover {
  color: var(--primary-dark);
}

@media (max-width: 900px) {
  .voting-card-square {
    width: 120px;
    height: 120px;
    font-size: 1.1rem;
    min-width: 80px;
    min-height: 80px;
  }
  .voting-card-title {
    font-size: 1.1rem;
  }
  .voting-modal {
    max-width: 98vw;
    min-width: 0;
    padding: 18px 6px 12px 6px;
  }
}
@media (max-width: 600px) {
  .row {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }
  .voting-card-square {
    width: 90px;
    height: 90px;
    font-size: 0.95rem;
    min-width: 60px;
    min-height: 60px;
  }
  .voting-card-title {
    font-size: 0.95rem;
  }
  .voting-modal {
    max-width: 99vw;
    min-width: 0;
    padding: 10px 2px 8px 2px;
  }
}
