us: var(--radius) var(--radius) 0 0;\r\n  margin-bottom: 14px;\r\n  display: block;\r\n}\r\n\r\n.voting-title {\r\n  font-size: 1.4rem;\r\n  color: var(--primary-dark);\r\n  margin-bottom: 8px;\r\n}\r\n\r\n.voting-meta {\r\n  display: flex;\r\n  gap: 18px;\r\n  font-size: 0.98rem;\r\n  color: #64748b;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.badge {\r\n  display: inline-block;\r\n  padding: 4px 14px;\r\n  border-radius: 999px;\r\n  font-size: 0.92rem;\r\n  font-weight: 600;\r\n  margin-right: 8px;\r\n}\r\n.badge-custom {\r\n  background: var(--badge-active);\r\n  color: #276749;\r\n}\r\n.bg-secondary, .badge.bg-secondary {\r\n  background: var(--badge-completed);\r\n  color: #97266d;\r\n}\r\n\r\n/* Исправления для выравнивания и современного вида */\r\n.d-flex {\r\n  display: flex !important;\r\n}\r\n.justify-content-between {\r\n  justify-content: space-between !important;\r\n}\r\n.align-items-center {\r\n  align-items: center !important;\r\n}\r\n.mb-4 {\r\n  margin-bottom: 1.5rem !important;\r\n}\r\n.mb-3 {\r\n  margin-bottom: 1rem !important;\r\n}\r\n.mb-2 {\r\n  margin-bottom: 0.5rem !important;\r\n}\r\n.py-4 {\r\n  padding-top: 1.5rem !important;\r\n  padding-bottom: 1.5rem !important;\r\n}\r\n.py-5 {\r\n  padding-top: 2.5rem !important;\r\n  padding-bottom: 2.5rem !important;\r\n}\r\n.text-center {\r\n  text-align: center !important;\r\n}\r\n\r\n/* Кнопки */\r\n.btn, .button {\r\n  background: var(--primary);\r\n  color: #fff;\r\n  border: none;\r\n  border-radius: var(--radius);\r\n  padding: 10px 24px;\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, box-shadow 0.2s;\r\n  margin: 8px 0;\r\n  box-shadow: 0 2px 8px rgba(127, 156, 245, 0.08);\r\n  display: inline-block;\r\n  text-align: center;\r\n  text-decoration: none;\r\n}\r\n.btn-primary, .btn-primary-custom {\r\n  background: var(--accent);\r\n  color: #fff;\r\n}\r\n.btn-primary:hover, .btn-primary-custom:hover {\r\n  background: #dd6b20;\r\n}\r\n.btn-outl